const feeDue = [3500, 3500, 4200, 4200, 5000];
const paid   = [3500, 2000, 4200, 1000, 5000];
const names  = ["Ali Raza", "Ayesha Khan", "Bilal Ahmed", "Hina Riaz", "Farhan Ali"];

let totalDue = 0, totalPaid = 0;
for (let i = 0; i < names.length; i++) {
  const balance = feeDue[i] - paid[i];
  totalDue += feeDue[i];
  totalPaid += paid[i];
  console.log(names[i], "| balance:", balance, balance > 0 ? "<- reminder" : "");
}
console.log("---");
