function markReminders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Fees');
  const lastRow = sheet.getLastRow();
  for (let r = 2; r <= lastRow; r++) {
    const balance = sheet.getRange(r, 5).getValue();
    if (typeof balance === 'number' && balance > 0) {
      sheet.getRange(r, 6).setValue('Reminder needed');
    } else {
      sheet.getRange(r, 6).setValue('');
    }
  }
}

@Apps Script
function dailySummary() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Fees');
  const values = sheet.getRange(2, 4, sheet.getLastRow() - 1, 1).getValues();
  let collected = 0;
  values.forEach(function (row) {
    if (typeof row[0] === 'number') collected += row[0];
  });
  Logger.log('Collected today: ' + collected);
}
